CREATE FUNCTION pg_temp.team_check(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAILED: %',message; END IF; END $$;
CREATE FUNCTION pg_temp.team_reject(statement text,expected text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN EXECUTE statement;RAISE EXCEPTION 'Unexpected success: %',statement; EXCEPTION WHEN OTHERS THEN IF SQLSTATE<>expected THEN RAISE; END IF; END $$;
GRANT EXECUTE ON FUNCTION pg_temp.team_check(boolean,text),pg_temp.team_reject(text,text) TO authenticated,anon,service_role;
