SELECT pg_temp.team_check((public.assign_booking_instructor('e8310000-0000-0000-0005-000000000001','e8310000-0000-0000-0006-000000000001')->>'version')::uuid=(SELECT assignment FROM team_tokens),'Same assignment retry preserves version');
SELECT public.save_centre_instructor('e8310000-0000-0000-0006-000000000001','Nome aggiornato',false,member) FROM team_tokens;
