SELECT pg_temp.team_reject($q$SELECT public.assign_booking_instructor('e8310000-0000-0000-0005-000000000002','e8310000-0000-0000-0006-000000000001')$q$,'22023');
SELECT pg_temp.team_reject($q$SELECT * FROM pc_private.booking_instructors$q$,'42501');
