SELECT pg_temp.team_check((SELECT count(*)=1 FROM pc_private.service_review_threads WHERE professional_id='e8310000-0000-0000-0000-000000000006' AND review_scope='booking_service'),'Second lesson review stays attached to service, not instructor');
SELECT pg_temp.team_check((SELECT count(*)=1 FROM pc_private.centre_team_history WHERE kind='assignment' AND booking_id='e8310000-0000-0000-0005-000000000001'),'Retry creates a single history event');
SELECT pg_temp.team_check((SELECT bool_and(relrowsecurity) FROM pg_class WHERE oid IN ('pc_private.centre_instructors'::regclass,'pc_private.booking_instructors'::regclass,'pc_private.centre_team_history'::regclass)),'RLS enabled');
SET ROLE service_role;
SELECT pg_temp.team_reject('SELECT * FROM pc_private.centre_team_history','42501');
RESET ROLE;
-- Account removal must not be blocked by roster/assignment foreign keys.
BEGIN;
DELETE FROM public.professionals WHERE id='e8310000-0000-0000-0000-000000000006';
SELECT pg_temp.team_check(NOT EXISTS(SELECT 1 FROM pc_private.booking_instructors WHERE centre_id='e8310000-0000-0000-0000-000000000006'),'Centre deletion removes active assignments');
SELECT pg_temp.team_check(EXISTS(SELECT 1 FROM pc_private.centre_team_history WHERE centre_id IS NULL AND kind='assignment'),'Private audit survives centre removal');
ROLLBACK;
